  "prod.wallet.balance": { en: "Total Balance", es: "Balance Total", fr: "Solde Total", pt: "Saldo Total", de: "Gesamtguthaben", zh: "\u603b\u4f59\u989d", ar: "\u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a", th: "\u0e22\u0e2d\u0e14\u0e04\u0e07\u0e40\u0e2b\u0e25\u0e37\u0e2d\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14" },
  "prod.wallet.desc": { en: "The user's entry point to the QFS ecosystem. Manage different types of digital assets from a single interface with advanced security.", es: "El punto de acceso del usuario al ecosistema QFS. Gestione diferentes tipos de activos digitales desde una \u00fanica interfaz con seguridad avanzada.", fr: "Le point d'acc\u00e8s des utilisateurs \u00e0 l'\u00e9cosyst\u00e8me QFS. G\u00e9rez diff\u00e9rents types d'actifs num\u00e9riques depuis une seule interface avec une s\u00e9curit\u00e9 avanc\u00e9e.", pt: "O ponto de acesso do usu\u00e1rio ao ecossistema QFS. Gerencie diferentes tipos de ativos digitais de uma \u00fanica interface com seguran\u00e7a avan\u00e7ada.", de: "Der Zugangspunkt der Benutzer zum QFS-\u00d6kosystem. Verwalten Sie verschiedene digitale Asset-Typen von einer einzigen Oberfl\u00e4che mit fortschrittlicher Sicherheit.", zh: "\u7528\u6237\u8fdb\u5165QFS\u751f\u6001\u7cfb\u7edf\u7684\u5165\u53e3\u3002\u901a\u8fc7\u5177\u6709\u9ad8\u7ea7\u5b89\u5168\u6027\u7684\u5355\u4e00\u754c\u9762\u7ba1\u7406\u5404\u79cd\u6570\u5b57\u8d44\u4ea7\u3002", ar: "\u0646\u0642\u0637\u0629 \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0625\u0644\u0649 \u0646\u0638\u0627\u0645 QFS. \u0625\u062f\u0627\u0631\u0629 \u0623\u0646\u0648\u0627\u0639 \u0645\u062e\u062a\u0644\u0641\u0629 \u0645\u0646 \u0627\u0644\u0623\u0635\u0648\u0644 \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0645\u0646 \u0648\u0627\u062c\u0647\u0629 \u0648\u0627\u062d\u062f\u0629 \u0628\u0623\u0645\u0627\u0646 \u0645\u062a\u0642\u062f\u0645.", th: "\u0e08\u0e38\u0e14\u0e40\u0e02\u0e49\u0e32\u0e16\u0e36\u0e07\u0e23\u0e30\u0e1a\u0e1a\u0e19\u0e34\u0e40\u0e27\u0e28 QFS \u0e02\u0e2d\u0e07\u0e1c\u0e39\u0e49\u0e43\u0e0a\u0e49 \u0e08\u0e31\u0e14\u0e01\u0e32\u0e23\u0e2a\u0e34\u0e19\u0e17\u0e23\u0e31\u0e1e\u0e22\u0e4c\u0e14\u0e34\u0e08\u0e34\u0e17\u0e31\u0e25\u0e2b\u0e25\u0e32\u0e22\u0e1b\u0e23\u0e30\u0e40\u0e20\u0e17\u0e08\u0e32\u0e01\u0e2d\u0e34\u0e19\u0e40\u0e17\u0e2d\u0e23\u0e4c\u0e40\u0e1f\u0e0b\u0e40\u0e14\u0e35\u0e22\u0e27\u0e1e\u0e23\u0e49\u0e2d\u0e21\u0e04\u0e27\u0e32\u0e21\u0e1b\u0e25\u0e2d\u0e14\u0e20\u0e31\u0e22\u0e02\u0e31\u0e49\u0e19\u0e2a\u0e39\u0e07" },
