  "why.innovation.desc": { en: "Blockchain + AI + Cryptography + Digital Finance.", es: "Blockchain + IA + Criptograf\u00eda + Finanzas Digitales.", fr: "Blockchain + IA + Cryptographie + Finances Num\u00e9riques.", pt: "Blockchain + IA + Criptografia + Finan\u00e7as Digitais.", de: "Blockchain + KI + Kryptografie + Digitale Finanzen.", zh: "\u533a\u5757\u94fe + AI + \u52a0\u5bc6\u672f + \u6570\u5b57\u91d1\u878d\u3002", ar: "\u0627\u0644\u0628\u0644\u0648\u0643\u062a\u0634\u064a\u0646 + \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a + \u0627\u0644\u062a\u0634\u0641\u064a\u0631 + \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0631\u0642\u0645\u064a.", th: "\u0e1a\u0e25\u0e47\u0e2d\u0e01\u0e40\u0e0a\u0e19 + AI + \u0e01\u0e32\u0e23\u0e40\u0e02\u0e49\u0e32\u0e23\u0e2b\u0e31\u0e2a + \u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e14\u0e34\u0e08\u0e34\u0e17\u0e31\u0e25" },
  "why.interop": { en: "Interoperability", es: "Interoperabilidad", fr: "Interop\u00e9rabilit\u00e9", pt: "Interoperabilidade", de: "Interoperabilit\u00e4t", zh: "\u4e92\u64cd\u4f5c\u6027", ar: "\u0627\u0644\u062a\u0634\u0627\u0628\u0643\u064a\u0629", th: "\u0e01\u0e32\u0e23\u0e17\u0e33\u0e07\u0e32\u0e19\u0e23\u0e48\u0e27\u0e21\u0e01\u0e31\u0e19" },
  "why.interop.desc": { en: "Connection between different networks and assets.", es: "Conexi\u00f3n entre diferentes redes y activos.", fr: "Connexion entre diff\u00e9rents r\u00e9seaux et actifs.", pt: "Conex\u00e3o entre diferentes redes e ativos.", de: "Verbindung zwischen verschiedenen Netzwerken und Assets.", zh: "\u4e0d\u540c\u7f51\u7edc\u548c\u8d44\u4ea7\u4e4b\u95f4\u7684\u8fde\u63a5\u3002", ar: "\u0627\u0644\u062a\u0631\u0627\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u0634\u0628\u0643\u0627\u062a \u0648\u0627\u0644\u0623\u0635\u0648\u0644 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629.", th: "\u0e01\u0e32\u0e23\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e21\u0e15\u0e48\u0e2d\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07\u0e40\u0e04\u0e23\u0e37\u0e2d\u0e02\u0e48\u0e32\u0e22\u0e41\u0e25\u0e30\u0e2a\u0e34\u0e19\u0e17\u0e23\u0e31\u0e1e\u0e22\u0e4c\u0e15\u0e48\u0e32\u0e07\u0e46" },
  "why.security": { en: "Security", es: "Seguridad", fr: "S\u00e9curit\u00e9", pt: "Seguran\u00e7a", de: "Sicherheit", zh: "\u5b89\u5168", ar: "\u0627\u0644\u0623\u0645\u0627\u0646", th: "\u0e04\u0e27\u0e32\u0e21\u0e1b\u0e25\u0e2d\u0e14\u0e20\u0e31\u0e22" },
  "why.security.desc": { en: "Infrastructure designed with security as absolute priority.", es: "Infraestructura dise\u00f1ada con seguridad como prioridad absoluta.", fr: "Infrastructure con\u00e7ue avec la s\u00e9curit\u00e9 comme priorit\u00e9 absolue.", pt: "Infraestrutura projetada com seguran\u00e7a como prioridade absoluta.", de: "Infrastruktur mit Sicherheit als absolutem Priorit\u00e4t.", zh: "\u4ee5\u5b89\u5168\u4e3a\u7edd\u5bf9\u4f18\u5148\u4e8b\u9879\u8bbe\u8ba1\u7684\u57fa\u7840\u8bbe\u65bd\u3002", ar: "\u0628\u0646\u064a\u0629 \u062a\u062d\u062a\u064a\u0627 \u0627\u0644\u0623\u0645\u0627\u0646 \u0643\u0623\u0648\u0644\u0648\u064a\u0629 \u0645\u0637\u0644\u0642\u0629.", th: "\u0e42\u0e04\u0e23\u0e07\u0e2a\u0e23\u0e49\u0e32\u0e07\u0e1e\u0e37\u0e49\u0e19\u0e10\u0e32\u0e19\u0e17\u0e35\u0e48\u0e2d\u0e2d\u0e01\u0e41\u0e1a\u0e1a\u0e42\u0e14\u0e22\u0e43\u0e2b\u0e49\u0e04\u0e27\u0e32\u0e21\u0e1b\u0e25\u0e2d\u0e14\u0e20\u0e31\u0e22\u0e40\u0e1b\u0e47\u0e19\u0e2d\u0e31\u0e19\u0e14\u0e31\u0e1a\u0e2b\u0e19\u0e36\u0e48\u0e07" },
  "why.speed": { en: "Speed", es: "Velocidad", fr: "Vitesse", pt: "Velocidade", de: "Geschwindigkeit", zh: "\u901f\u5ea6", ar: "\u0627\u0644\u0633\u0631\u0639\u0629", th: "\u0e04\u0e27\u0e32\u0e21\u0e40\u0e23\u0e47\u0e27" },
  "why.speed.desc": { en: "Efficient and scalable digital processing.", es: "Procesamiento digital eficiente y escalable.", fr: "Traitement num\u00e9rique efficace et \u00e9volutif.", pt: "Processamento digital eficiente e escal\u00e1vel.", de: "Effiziente und skalierbare digitale Verarbeitung.", zh: "\u9ad8\u6548\u53ef\u6269\u5c55\u7684\u6570\u5b57\u5904\u7406\u3002", ar: "\u0645\u0639\u0627\u0644\u062c\u0629 \u0631\u0642\u0645\u064a\u0629 \u0641\u0639\u0627\u0644\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0648\u0633\u0639.", th: "\u0e01\u0e32\u0e23\u0e1b\u0e23\u0e30\u0e21\u0e27\u0e25\u0e1c\u0e25\u0e14\u0e34\u0e08\u0e34\u0e17\u0e31\u0e25\u0e17\u0e35\u0e48\u0e21\u0e35\u0e1b\u0e23\u0e30\u0e2a\u0e34\u0e17\u0e18\u0e34\u0e20\u0e32\u0e1e\u0e41\u0e25\u0e30\u0e02\u0e22\u0e32\u0e22\u0e44\u0e14\u0e49" },
  "why.subtitle": { en: "Why QFS", es: "Por qu\u00e9 QFS", fr: "Pourquoi QFS", pt: "Por que QFS", de: "Warum QFS", zh: "\u4e3a\u4ec0\u4e48\u9009QFS", ar: "\u0644\u0645\u0627\u0630\u0627 QFS", th: "\u0e17\u0e33\u0e44\u0e21\u0e15\u0e49\u0e2d\u0e07 QFS" },
  "why.title": { en: "Why QFS?", es: "\u00bfPor qu\u00e9 QFS?", fr: "Pourquoi QFS ?", pt: "Por que QFS?", de: "Warum QFS?", zh: "\u4e3a\u4ec0\u4e48\u9009QFS\uff1f", ar: "\u0644\u0645\u0627\u0630\u0627 QFS\u061f", th: "\u0e17\u0e33\u0e44\u0e21\u0e15\u0e49\u0e2d\u0e07 QFS?" },
  "why.transparency": { en: "Transparency", es: "Transparencia", fr: "Transparence", pt: "Transpar\u00eancia", de: "Transparenz", zh: "\u900f\u660e\u5ea6", ar: "\u0627\u0644\u0634\u0641\u0627\u0641\u064a\u0629", th: "\u0e04\u0e27\u0e32\u0e21\u0e42\u0e1b\u0e23\u0e48\u0e07\u0e43\u0e2a" },
  "why.transparency.desc": { en: "Blockchain technology and verifiable records.", es: "Tecnolog\u00eda blockchain y registros verificables.", fr: "Technologie blockchain et registres v\u00e9rifiables.", pt: "Tecnologia blockchain e registros verific\u00e1veis.", de: "Blockchain-Technologie und \u00fcberpr\u00fcfbare Aufzeichnungen.", zh: "\u533a\u5757\u94fe\u6280\u672f\u548c\u53ef\u9a8c\u8bc1\u8bb0\u5f55\u3002", ar: "\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0628\u0644\u0648\u0643\u062a\u0634\u064a\u0646 \u0648\u0633\u062c\u0644\u0627\u062a \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u062d\u0642\u0642.", th: "\u0e40\u0e17\u0e04\u0e42\u0e19\u0e42\u0e25\u0e22\u0e35\u0e1a\u0e25\u0e47\u0e2d\u0e01\u0e40\u0e0a\u0e19\u0e41\u0e25\u0e30\u0e1a\u0e31\u0e19\u0e17\u0e36\u0e01\u0e17\u0e35\u0e48\u0e15\u0e23\u0e27\u0e08\u0e2a\u0e2d\u0e1a\u0e44\u0e14\u0e49" },
  "wp.badge": { en: "WHITE PAPER", es: "LIBRO BLANCO", fr: "LIVRE BLANC", pt: "LIVRO BRANCO", de: "WHITEPAPER", zh: "\u767d\u76ae\u4e66", ar: "\u0627\u0644\u0648\u062b\u064a\u0642\u0629 \u0627\u0644\u062a\u0641\u0635\u064a\u0644\u064a\u0629", th: "\u0e40\u0e2d\u0e01\u0e2a\u0e32\u0e23\u0e02\u0e32\u0e27" },
